import {useEffect,useState} from "react";

function Internships(){

const [jobs,setJobs]=useState([]);

const [year,setYear]=useState("");

const [branch,setBranch]=useState("");


useEffect(()=>{

fetch("http://localhost:5000/api/jobs?jobType=FullTime")

.then(res=>res.json())

.then(data=>setJobs(data));

},[]);


function applyFilter(){

fetch(`http://localhost:5000/api/jobs?jobType=FullTime&eligibleYear=${year}&branch=${branch}`)

.then(res=>res.json())

.then(data=>setJobs(data));

}


return(

<div className="page">

<h1>Internships</h1>


<div className="filters">

<select onChange={(e)=>setYear(e.target.value)}>

<option value="">All Years</option>

<option>1st</option>

<option>2nd</option>

<option>3rd</option>

<option>4th</option>

</select>


<select onChange={(e)=>setBranch(e.target.value)}>

<option value="">All Branches</option>

<option>CSE</option>

<option>IT</option>

<option>ECE</option>

<option>EEE</option>

<option>MECH</option>

<option>CIVIL</option>

</select>


<button onClick={applyFilter}>
Apply Filter
</button>

</div>



<div className="jobs">

{jobs.map(job=>(

<div className="card" key={job.jobId}>

<h3>{job.title}</h3>

<p>{job.company}</p>

<p>{job.location}</p>

<p>{job.jobType}</p>

<p>

Eligible:
{job.eligibleYears?.join(",")}

</p>

<a href={job.applyLink} target="_blank">
Apply
</a>

</div>

))}

</div>

</div>

)

}

export default Internships;
